package kr.workbench;
import burp.api.montoya.MontoyaApi;import burp.api.montoya.http.*;import burp.api.montoya.http.message.requests.HttpRequest;
import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import java.util.function.Consumer;import java.util.regex.*;
/** Explicit, serial, same-origin workflow runner. Never starts on traffic capture. */
final class BountyWorkflow {
 record Step(String raw){}
 record Extract(int step,String name,String path){}
 record Plan(String origin,List<Step> steps,List<Extract> extracts,boolean writes,int timeout,int budget){Plan{steps=List.copyOf(steps);extracts=List.copyOf(extracts);}}
 record Result(int step,HttpRequest request,burp.api.montoya.http.message.responses.HttpResponse response,String state){}
 static Plan parse(String origin,String text,String extraction,boolean writes,int timeout,int budget){
  URI u=URI.create(origin);if(u.getUserInfo()!=null||u.getHost()==null||!Set.of("http","https").contains(u.getScheme())||!Objects.toString(u.getRawPath(),"").matches("/?")||u.getRawQuery()!=null||u.getFragment()!=null)throw new IllegalArgumentException("대상은 http(s)://호스트:포트 Origin만 입력하세요.");
  if(text.length()>128*1024||extraction.length()>4096||timeout<1||timeout>120||budget<1||budget>20)throw new IllegalArgumentException("워크플로 크기/요청 한도 오류");
  List<Step> steps=new ArrayList<>();for(String raw:text.split("(?m)(?:\\r?\\n)?^===STEP===[ \\t]*(?:\\r?\\n|$)"))if(!raw.isBlank())steps.add(new Step(raw.stripLeading()));if(steps.isEmpty()||steps.size()>8||steps.size()>budget)throw new IllegalArgumentException("단계는 1~8개이고 총 요청 한도 이하여야 합니다.");
  List<Extract> extracts=new ArrayList<>();Set<String> names=new HashSet<>();for(String line:extraction.split("\\R")){if(line.isBlank())continue;var m=Pattern.compile("([1-8])\\.([A-Za-z][A-Za-z0-9_]{0,31})=(\\$\\..{1,120})").matcher(line.strip());if(!m.matches()||Integer.parseInt(m.group(1))>steps.size()||!names.add(m.group(2)))throw new IllegalArgumentException("추출: 1.id=$.id · 변수 이름은 중복 없이 지정하세요.");extracts.add(new Extract(Integer.parseInt(m.group(1)),m.group(2),m.group(3)));if(extracts.size()>32)throw new IllegalArgumentException("추출 변수 최대 32개");}
  Plan plan=new Plan(origin,steps,extracts,writes,timeout,budget);Map<String,Object> declared=new LinkedHashMap<>();for(int i=0;i<steps.size();i++){request(plan,expand(steps.get(i).raw,declared));for(Extract e:extracts)if(e.step==i+1)declared.put(e.name,"PREVIEW");}return plan;
 }
 static String expand(String raw,Map<String,Object> vars){var m=Pattern.compile("\\{\\{([A-Za-z][A-Za-z0-9_]{0,31})\\|(URL|JSON|RAW)}}").matcher(raw);StringBuffer s=new StringBuffer();while(m.find()){Object value=vars.get(m.group(1));if(value==null)throw new IllegalArgumentException("앞 단계 변수 없음 · "+m.group(1));String text=String.valueOf(value);BountySession.validValue(text);String encoded=switch(m.group(2)){case "URL"->URLEncoder.encode(text,StandardCharsets.UTF_8).replace("+","%20");case "JSON"->MetadataExport.json(value);default->text;};m.appendReplacement(s,Matcher.quoteReplacement(encoded));}m.appendTail(s);if(s.indexOf("{{")>=0)throw new IllegalArgumentException("변수는 {{id|URL}}, {{id|JSON}}, {{id|RAW}} 형식입니다.");if(s.length()>128*1024)throw new IllegalArgumentException("치환 요청 크기 제한");return s.toString();}
 static HttpRequest request(Plan plan,String raw){
  int boundary=raw.indexOf("\r\n\r\n"),width=4;int lf=raw.indexOf("\n\n");if(boundary<0||(lf>=0&&lf<boundary)){boundary=lf;width=2;}String head=boundary<0?raw:raw.substring(0,boundary),body=boundary<0?"":raw.substring(boundary+width);String[] lines=head.replace("\r\n","\n").split("\n");String[] first=lines[0].split(" ");if(first.length!=3||!first[1].startsWith("/")||first[1].startsWith("//")||!first[2].equals("HTTP/1.1")||!Set.of("GET","HEAD","OPTIONS","POST","PUT","PATCH","DELETE").contains(first[0]))throw new IllegalArgumentException("단계 요청은 상대 경로의 HTTP/1.1 요청이어야 합니다.");
  if(!plan.writes&&!Core.readMethod(first[0]))throw new IllegalArgumentException("쓰기 단계 실행 옵션이 필요합니다.");URI u=URI.create(plan.origin);String host=u.getRawAuthority();int hostCount=0;
  for(int i=1;i<lines.length;i++){String line=lines[i];if(line.isBlank())continue;int k=line.indexOf(':');if(k<1||line.startsWith(" ")||line.startsWith("\t"))throw new IllegalArgumentException("헤더 형식 오류");String name=line.substring(0,k);if(name.equalsIgnoreCase("host")){hostCount++;URI hu=URI.create(u.getScheme()+"://"+line.substring(k+1).strip());int hp=hu.getPort()<0?(u.getScheme().equals("https")?443:80):hu.getPort(),up=u.getPort()<0?(u.getScheme().equals("https")?443:80):u.getPort();if(hu.getUserInfo()!=null||hu.getHost()==null||!hu.getHost().equalsIgnoreCase(u.getHost())||hp!=up||!Objects.toString(hu.getRawPath(),"").isEmpty()||hu.getRawQuery()!=null||hu.getFragment()!=null)throw new IllegalArgumentException("Host는 설정한 Origin과 같아야 합니다.");}if(name.equalsIgnoreCase("transfer-encoding")||name.equalsIgnoreCase("content-encoding"))throw new IllegalArgumentException("압축/chunked 요청은 정상화 후 사용하세요.");}
  if(hostCount!=1)throw new IllegalArgumentException("Host 헤더는 정확히 하나 필요합니다.");int port=u.getPort()<0?(u.getScheme().equals("https")?443:80):u.getPort();HttpRequest q=HttpRequest.httpRequest(HttpService.httpService(u.getHost(),port,u.getScheme().equals("https")),head.replace("\r\n","\n").replace("\n","\r\n")+"\r\n\r\n");
  if(boundary>=0)q=q.withBody(body);return q;
 }
 record Check(int step,String path,String expected){}
 static List<Check> checks(Plan plan,String text){if(text.length()>4096)throw new IllegalArgumentException("기대 조건 4KB 제한");List<Check> out=new ArrayList<>();for(String line:text.split("\\R")){if(line.isBlank())continue;var m=Pattern.compile("([1-8])\\.(HTTP|\\$\\.[^=]{1,120})=(.{1,256})").matcher(line.strip());if(!m.matches()||Integer.parseInt(m.group(1))>plan.steps.size())throw new IllegalArgumentException("기대 조건: 1.HTTP=200 / 2.$.state=READY");if(m.group(2).equals("HTTP")&&!m.group(3).matches("[1-5][0-9]{2}"))throw new IllegalArgumentException("HTTP 기대값은 상태 코드입니다.");out.add(new Check(Integer.parseInt(m.group(1)),m.group(2),m.group(3)));if(out.size()>32)throw new IllegalArgumentException("기대 조건 최대 32개");}return List.copyOf(out);}
 static void run(MontoyaApi api,Plan plan,AtomicBoolean cancel,Consumer<Result> results)throws Exception{run(api,plan,cancel,results,List.of());}
 static void run(MontoyaApi api,Plan plan,AtomicBoolean cancel,Consumer<Result> results,List<Check> checks)throws Exception{
  Map<String,Object> vars=new LinkedHashMap<>();for(int i=0;i<plan.steps.size();i++){if(cancel.get())return;HttpRequest q=request(plan,expand(plan.steps.get(i).raw,vars));
   if(!WorkbenchScope.contains(api,q)||!AuthComparePanel.origin(q).equals(AuthComparePanel.origin(HttpRequest.httpRequestFromUrl(plan.origin))))throw new IllegalArgumentException("단계가 SCOPE/Origin 밖입니다.");
   var rr=api.http().sendRequest(q,RequestOptions.requestOptions().withResponseTimeout(plan.timeout*1000).withRedirectionMode(RedirectionMode.NEVER));var response=rr==null?null:rr.response();String state="관측 완료 · 최종 상태 수동 확인";
   if(response==null)state="응답 없음 · 후속 단계 중단";else if(response.toByteArray().length()>128*1024){state="응답 한도 초과 · 후속 단계 중단";response=null;}else if(Set.of(401,403,429,503).contains((int)response.statusCode())||response.statusCode()<200||response.statusCode()>=300)state="HTTP "+response.statusCode()+" · 후속 단계 중단";
   if(rr!=null&&rr.request()!=null&&(!WorkbenchScope.contains(api,rr.request())||!AuthComparePanel.sameTarget(rr.request(),q)))state="실제 전송 대상/메서드/Scope 변경 · 후속 단계 중단";
   if(!state.contains("중단")&&response!=null){boolean checked=false;for(Check check:checks)if(check.step==i+1){checked=true;Object value=check.path.equals("HTTP")?response.statusCode():AuthJudgement.value(Objects.requireNonNullElse(AuthJudgement.json(JsAnalysisPanel.readBody(response)),Map.of()),check.path);if(value==null||!String.valueOf(value).equals(check.expected)){state="기대 조건 불일치 · "+check.path+" · 후속 단계 중단";break;}}if(checked&&!state.contains("중단"))state="기대 조건 일치 · 지정한 조건만 검증";}
   if(!state.contains("중단")&&response!=null){try{var json=AuthJudgement.json(JsAnalysisPanel.readBody(response));for(Extract e:plan.extracts)if(e.step==i+1){BountySession.scalar(json,e.path);vars.put(e.name,AuthJudgement.value(json,e.path));}}catch(Exception ex){state="응답 변수 추출 실패 · 후속 단계 중단";results.accept(new Result(i+1,rr!=null&&rr.request()!=null?rr.request():q,response,state));throw ex;}}
   results.accept(new Result(i+1,rr!=null&&rr.request()!=null?rr.request():q,response,state));if(state.contains("중단")||cancel.get())return;
   }
  
 }
}
